@import "@fontsource-variable/inter";
@import "@fontsource/inria-serif/300-italic.css";
@import "@fontsource/inria-serif/400-italic.css";
@import "@fontsource/inria-serif/400.css";

/* Light (faithful): paper white page, pinker light surface for bands and tiles, espresso ink,
   warm grey text, and a taupe → sand brand gradient (primary → highlight). */
:root {
  --background: #faf9f4;
  --foreground: #2b221c;
  --card: #f5f1ed;
  --card-foreground: #2b221c;
  --popover: #faf9f4;
  --popover-foreground: #2b221c;
  --primary: #a48a7a;
  --primary-foreground: #faf9f4;
  --secondary: #cbbba0;
  --secondary-foreground: #2b221c;
  --muted: #f5f1ed;
  --muted-foreground: #6b6561;
  --accent: #cbbba0;
  --accent-foreground: #2b221c;
  --destructive: #b4533c;
  --destructive-foreground: #faf9f4;
  --border: rgb(164 138 122 / 25%);
  --input: rgb(164 138 122 / 25%);
  --ring: #a48a7a;
  --highlight: #cbbba0;
  --highlight-foreground: #2b221c;
  --glow: #cbbba0;
  --chart-1: #a48a7a;
  --chart-2: #cbbba0;
  --chart-3: #6b6561;
  --chart-4: #2b221c;
  --chart-5: #e2d6c4;
  --sidebar: #f5f1ed;
  --sidebar-foreground: #2b221c;
  --sidebar-primary: #a48a7a;
  --sidebar-primary-foreground: #faf9f4;
  --sidebar-accent: #cbbba0;
  --sidebar-accent-foreground: #2b221c;
  --sidebar-border: rgb(164 138 122 / 25%);
  --sidebar-ring: #a48a7a;

  --typeface-body: "Inter Variable", "Inter", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inria Serif", ui-serif, Georgia, "Times New Roman", serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem;
  /* the content column, 1160px (blocks pad the section with the gutter and centre this inside) */
  --page-width: 72.5rem;
  --page-gutter: 1.125rem;
  --section-y: 4.5rem;
}

@media (min-width: 48rem) {
  :root {
    --page-gutter: 3rem;
    --section-y: 6rem;
  }
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 5rem;
    --section-y: 7.5rem;
  }
}

/* Dark (sibling): deep espresso page, a lifted espresso surface, cream text, the same taupe
   and sand. */
.dark {
  --background: #1d1714;
  --foreground: #f3ede4;
  --card: #2a221d;
  --card-foreground: #f3ede4;
  --popover: #2a221d;
  --popover-foreground: #f3ede4;
  --primary: #a48a7a;
  --primary-foreground: #faf9f4;
  --secondary: #5a4a3f;
  --secondary-foreground: #f3ede4;
  --muted: #2a221d;
  --muted-foreground: #b8aca1;
  --accent: #cbbba0;
  --accent-foreground: #1d1714;
  --destructive: #d0705a;
  --destructive-foreground: #1d1714;
  --border: rgb(203 187 160 / 22%);
  --input: rgb(203 187 160 / 22%);
  --ring: #cbbba0;
  --highlight: #cbbba0;
  --highlight-foreground: #1d1714;
  --glow: #8a7262;
  --chart-1: #a48a7a;
  --chart-2: #cbbba0;
  --chart-3: #b8aca1;
  --chart-4: #f3ede4;
  --chart-5: #5a4a3f;
  --sidebar: #2a221d;
  --sidebar-foreground: #f3ede4;
  --sidebar-primary: #a48a7a;
  --sidebar-primary-foreground: #1d1714;
  --sidebar-accent: #5a4a3f;
  --sidebar-accent-foreground: #f3ede4;
  --sidebar-border: rgb(203 187 160 / 22%);
  --sidebar-ring: #cbbba0;
}
